<?php
namespace App\Services;
use App\Core\Audit;use App\Core\Database;
final class PluginUpdateService
{
 public static function visibleServers():array{return Database::connection()->query('SELECT * FROM game_servers ORDER BY name')->fetchAll();}
 public static function inventoryForServer(int $serverId,bool $quick=true):array{
  $status=$quick?LiveServerService::statusQuick($serverId):LiveServerService::status($serverId);if(!$quick)self::reconcileRuns($serverId);$plugins=is_array($status['plugins']??null)?$status['plugins']:[];$sources=self::sourcesByPluginId();
  foreach($plugins as &$plugin){if(!is_array($plugin))$plugin=[];$id=(string)($plugin['id']??'');$source=$sources[$id]??null;$plugin['update_source']=$source;$plugin['suggested_repository']=GitHubReleaseService::repositoryFromWebsite($plugin['website']??null);$repo=(string)($source['repository']??$plugin['suggested_repository']??'');$plugin['github_repository_url']=self::githubRepositoryUrl($repo);$plugin['latest_version']=$source['latest_version']??null;$plugin['latest_tag']=$source['latest_tag']??null;$plugin['latest_release_url']=$source['latest_release_url']??null;$plugin['latest_asset_name']=$source['latest_asset_name']??null;$plugin['latest_asset_sha256']=$source['latest_asset_sha256']??null;$plugin['update_available']=$source?GitHubReleaseService::isNewer((string)($plugin['version']??''),(string)($source['latest_version']??'')):false;self::observeQueuedRun($serverId,$id,(string)($plugin['version']??''));}unset($plugin);
  usort($plugins,static fn(array $a,array $b):int=>strnatcasecmp((string)($a['name']??$a['id']??''),(string)($b['name']??$b['id']??'')));
  return ['bridge_online'=>!empty($status['bridge_online']),'bridge_version'=>$status['version']??null,'reason'=>$status['reason']??null,'plugins'=>$plugins];
 }
 public static function githubRepositoryUrl(?string $repository):?string{
  $repository=trim((string)$repository);if($repository==='')return null;
  try{$normalized=GitHubReleaseService::normalizeRepository($repository);}catch(\Throwable){return null;}
  [$owner,$repo]=explode('/',$normalized,2);
  return 'https://github.com/'.rawurlencode($owner).'/'.rawurlencode($repo);
 }
 public static function saveSource(string $pluginId,array $input):void{
  $pluginId=self::pluginId($pluginId);$repository=GitHubReleaseService::normalizeRepository((string)($input['repository']??''));$pattern=trim((string)($input['asset_pattern']??'*.zip'))?:'*.zip';$sub=trim((string)($input['install_subpath']??''));$channel=(string)($input['channel']??'stable');$mode=(string)($input['update_mode']??'check_only');$auto=!empty($input['auto_update']);
  if(!in_array($channel,['stable','prerelease'],true))$channel='stable';if(!in_array($mode,['check_only','reload'],true))$mode='check_only';if(str_contains($pattern,'/')||str_contains($pattern,'\\')||strlen($pattern)>160)throw new \InvalidArgumentException('Ungültiges Asset-Muster.');$lowerPattern=strtolower($pattern);if(!str_contains($lowerPattern,'.zip')&&!str_contains($lowerPattern,'.rar'))throw new \InvalidArgumentException('Asset-Muster muss ein ZIP- oder RAR-Release auswählen.');
  if($sub!==''){if(str_starts_with($sub,'/')||str_starts_with($sub,'\\')||str_contains($sub,'..'))throw new \InvalidArgumentException('Installations-Unterpfad muss relativ sein und darf kein ".." enthalten.');$sub=trim(str_replace('\\','/',$sub),'/');} if($auto&&$mode!=='reload')throw new \InvalidArgumentException('Auto-Update ist nur im Modus "Backup + kontrollierter Reload" erlaubt.');
  $now=date('c');Database::connection()->prepare('INSERT INTO plugin_update_sources(plugin_id,repository,asset_pattern,install_subpath,channel,update_mode,auto_update,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(plugin_id) DO UPDATE SET repository=excluded.repository,asset_pattern=excluded.asset_pattern,install_subpath=excluded.install_subpath,channel=excluded.channel,update_mode=excluded.update_mode,auto_update=excluded.auto_update,updated_at=excluded.updated_at')->execute([$pluginId,$repository,$pattern,$sub,$channel,$mode,$auto?1:0,$now,$now]);Audit::log('plugin.update_source.saved','plugin',$pluginId,['repository'=>$repository,'asset_pattern'=>$pattern,'channel'=>$channel,'update_mode'=>$mode,'auto_update'=>$auto]);
 }
 public static function deleteSource(string $pluginId):void{$pluginId=self::pluginId($pluginId);Database::connection()->prepare('DELETE FROM plugin_update_sources WHERE plugin_id=?')->execute([$pluginId]);Audit::log('plugin.update_source.deleted','plugin',$pluginId);}
 public static function checkSource(string $pluginId):array{$pluginId=self::pluginId($pluginId);$source=self::source($pluginId);if(!$source)throw new \RuntimeException('Für dieses Plugin ist keine GitHub-Updatequelle hinterlegt.');try{$latest=GitHubReleaseService::latest((string)$source['repository'],(string)$source['asset_pattern'],(string)$source['channel']);Database::connection()->prepare('UPDATE plugin_update_sources SET latest_version=?,latest_tag=?,latest_release_url=?,latest_asset_name=?,latest_asset_url=?,latest_asset_sha256=?,last_checked_at=?,last_error=NULL,updated_at=? WHERE plugin_id=?')->execute([$latest['version'],$latest['tag'],$latest['release_url'],$latest['asset_name'],$latest['asset_url'],$latest['asset_sha256'],date('c'),date('c'),$pluginId]);return $latest;}catch(\Throwable $e){Database::connection()->prepare('UPDATE plugin_update_sources SET last_checked_at=?,last_error=?,updated_at=? WHERE plugin_id=?')->execute([date('c'),$e->getMessage(),date('c'),$pluginId]);throw $e;}}
 public static function checkAllSources():array{$rows=Database::connection()->query('SELECT plugin_id FROM plugin_update_sources ORDER BY plugin_id')->fetchAll();$r=['checked'=>0,'ok'=>0,'errors'=>[]];foreach($rows as $row){$r['checked']++;try{self::checkSource((string)$row['plugin_id']);$r['ok']++;}catch(\Throwable $e){$r['errors'][(string)$row['plugin_id']]=$e->getMessage();}}return $r;}
 public static function checkDueSources(int $minAgeSeconds=3600):array{$minAgeSeconds=max(300,$minAgeSeconds);$st=Database::connection()->prepare('SELECT plugin_id FROM plugin_update_sources WHERE last_checked_at IS NULL OR last_checked_at<? ORDER BY plugin_id');$st->execute([date('c',time()-$minAgeSeconds)]);$r=['checked'=>0,'ok'=>0,'errors'=>[]];foreach($st->fetchAll() as $row){$r['checked']++;try{self::checkSource((string)$row['plugin_id']);$r['ok']++;}catch(\Throwable $e){$r['errors'][(string)$row['plugin_id']]=$e->getMessage();}}return $r;}
 public static function queueUpdate(int $serverId,string $pluginId,string $mode='manual',?int $createdBy=null):string{
  $pluginId=self::pluginId($pluginId);if($pluginId==='lplk.serververwaltung.bridge')throw new \RuntimeException('Die SerververwaltungBridge aktualisiert sich aus Sicherheitsgründen nicht selbst.');$source=self::source($pluginId);if(!$source)throw new \RuntimeException('Keine Updatequelle hinterlegt.');if((string)$source['update_mode']!=='reload')throw new \RuntimeException('Diese Quelle steht auf "nur prüfen".');$inv=self::inventoryForServer($serverId,false);$plugin=null;foreach($inv['plugins'] as $item)if((string)($item['id']??'')===$pluginId){$plugin=$item;break;}if(!$plugin)throw new \RuntimeException('Plugin ist auf diesem Server nicht geladen/erkannt.');$from=(string)($plugin['version']??'');$to=trim((string)($source['latest_version']??''));if($to===''||!GitHubReleaseService::isNewer($from,$to))throw new \RuntimeException('Es ist keine neuere geprüfte Version verfügbar.');$url=trim((string)($source['latest_asset_url']??''));$name=trim((string)($source['latest_asset_name']??''));if($url===''||$name==='')throw new \RuntimeException('Updatequelle wurde noch nicht erfolgreich gegen GitHub geprüft.');$sha=trim((string)($source['latest_asset_sha256']??''));if($mode==='auto'&&!preg_match('/^[a-f0-9]{64}$/',$sha))throw new \RuntimeException('Auto-Update wird ohne von GitHub gelieferten SHA-256-Digest nicht ausgeführt.');
  if($mode==='auto'){$st=Database::connection()->prepare("SELECT COUNT(*) FROM plugin_update_runs WHERE server_id=? AND plugin_id=? AND to_version=? AND created_at>=? AND status IN ('queued','success')");$st->execute([$serverId,$pluginId,$to,date('c',time()-1800)]);if((int)$st->fetchColumn()>0)throw new \RuntimeException('Dieses Update wurde in den letzten 30 Minuten bereits eingeplant.');}
  $cid=LiveServerService::queue($serverId,'plugin_update',['plugin_id'=>$pluginId,'download_url'=>$url,'asset_name'=>$name,'expected_sha256'=>$sha,'expected_version'=>$to,'install_subpath'=>(string)$source['install_subpath']]);Database::connection()->prepare('INSERT INTO plugin_update_runs(server_id,plugin_id,from_version,to_version,command_id,mode,status,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$serverId,$pluginId,$from,$to,$cid,$mode,'queued',$createdBy,date('c')]);Audit::log('plugin.update.queued','plugin',$pluginId,['server_id'=>$serverId,'from'=>$from,'to'=>$to,'mode'=>$mode,'command_id'=>$cid]);return $cid;
 }
 public static function queueRollback(int $serverId,string $pluginId,string $backupId,?int $createdBy=null):string{$pluginId=self::pluginId($pluginId);if($pluginId==='lplk.serververwaltung.bridge')throw new \RuntimeException('Die Bridge kann nicht über sich selbst zurückgerollt werden.');if(!preg_match('/^[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}$/',$backupId))throw new \InvalidArgumentException('Ungültige Backup-ID.');$cid=LiveServerService::queue($serverId,'plugin_rollback',['plugin_id'=>$pluginId,'backup_id'=>$backupId]);Database::connection()->prepare('INSERT INTO plugin_update_runs(server_id,plugin_id,command_id,mode,status,created_by,created_at,message) VALUES(?,?,?,?,?,?,?,?)')->execute([$serverId,$pluginId,$cid,'rollback','queued',$createdBy,date('c'),'Rollback auf '.$backupId]);Audit::log('plugin.rollback.queued','plugin',$pluginId,['server_id'=>$serverId,'backup_id'=>$backupId,'command_id'=>$cid]);return $cid;}
 public static function runAutoUpdates():array{$pdo=Database::connection();$sources=$pdo->query("SELECT * FROM plugin_update_sources WHERE auto_update=1 AND update_mode='reload' ORDER BY plugin_id")->fetchAll();$servers=$pdo->query('SELECT id,name FROM game_servers ORDER BY name')->fetchAll();$r=['queued'=>0,'skipped'=>0,'errors'=>[]];foreach($servers as $server){$sid=(int)$server['id'];try{$inv=self::inventoryForServer($sid,false);if(empty($inv['bridge_online'])){$r['skipped']++;continue;}$by=[];foreach($inv['plugins'] as $p)$by[(string)($p['id']??'')]=$p;foreach($sources as $source){$pid=(string)$source['plugin_id'];if(!isset($by[$pid]))continue;try{if(!GitHubReleaseService::isNewer((string)($by[$pid]['version']??''),(string)($source['latest_version']??'')))continue;self::queueUpdate($sid,$pid,'auto',null);$r['queued']++;}catch(\Throwable $e){$r['errors'][]=$server['name'].' / '.$pid.': '.$e->getMessage();}}}catch(\Throwable $e){$r['errors'][]=$server['name'].': '.$e->getMessage();}}return $r;}
 public static function sourcesByPluginId():array{$rows=Database::connection()->query('SELECT * FROM plugin_update_sources ORDER BY plugin_id')->fetchAll();$o=[];foreach($rows as $row)$o[(string)$row['plugin_id']]=$row;return $o;}
 public static function source(string $pluginId):?array{$st=Database::connection()->prepare('SELECT * FROM plugin_update_sources WHERE plugin_id=?');$st->execute([self::pluginId($pluginId)]);$r=$st->fetch();return $r?:null;}
 public static function recentRuns(int $limit=50):array{$limit=max(1,min(200,$limit));return Database::connection()->query("SELECT r.*,s.name AS server_name FROM plugin_update_runs r JOIN game_servers s ON s.id=r.server_id ORDER BY r.id DESC LIMIT {$limit}")->fetchAll();}
 private static function reconcileRuns(int $serverId):void{
  $st=Database::connection()->prepare("SELECT id,command_id FROM plugin_update_runs WHERE server_id=? AND status='queued' AND command_id IS NOT NULL ORDER BY id DESC LIMIT 20");$st->execute([$serverId]);
  foreach($st->fetchAll() as $row){try{$result=LiveServerService::result($serverId,(string)$row['command_id']);if(!$result)continue;$ok=!empty($result['success']);Database::connection()->prepare('UPDATE plugin_update_runs SET status=?,message=?,observed_at=? WHERE id=?')->execute([$ok?'success':'failed',(string)($result['message']??($ok?'OK':'Fehler')),date('c'),(int)$row['id']]);}catch(\Throwable){}}
 }
 private static function observeQueuedRun(int $serverId,string $pluginId,string $version):void{if($pluginId===''||$version==='')return;$st=Database::connection()->prepare("SELECT id,to_version FROM plugin_update_runs WHERE server_id=? AND plugin_id=? AND status='queued' ORDER BY id DESC LIMIT 5");$st->execute([$serverId,$pluginId]);foreach($st->fetchAll() as $row){if((string)$row['to_version']!==''&&!GitHubReleaseService::isNewer($version,(string)$row['to_version']))Database::connection()->prepare("UPDATE plugin_update_runs SET status='success',observed_at=?,message=? WHERE id=?")->execute([date('c'),'Neue Plugin-Version wurde im Bridge-Inventar beobachtet.',(int)$row['id']]);}}
 private static function pluginId(string $v):string{$v=trim($v);if(!preg_match('/^[A-Za-z0-9_.-]{1,100}$/',$v))throw new \InvalidArgumentException('Ungültige Plugin-ID.');return $v;}
}
